    );
  }

  const remoteRubricIds = new Set(
    remote.rubricResults.flatMap((entry) =>
      entry.folioId ? [entry.folioId] : [],
    ),
  );
  for (const entry of local.rubricResults) {
    if (!remoteRubricIds.has(entry.folioId)) {
